'use strict';

// MODULES //

var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var randu = require( '@stdlib/random/base/randu' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var isAlmostSameValue = require( '@stdlib/number/float32/base/assert/is-almost-same-value' );
var erfcinvf = require( './../lib' );


// FIXTURES //

var erfcinvf_0002_025 = require( './fixtures/julia/erfcinvf_0.0002_0.25.json' );
var erfcinvf_025_05 = require( './fixtures/julia/erfcinvf_0.25_0.5.json' );
var erfcinvf_05_15 = require( './fixtures/julia/erfcinvf_0.5_1.5.json' );
var erfcinvf_15_175 = require( './fixtures/julia/erfcinvf_1.5_1.75.json' );
var erfcinvf_175_19998 = require( './fixtures/julia/erfcinvf_1.75_1.9998.json' );
var erfcinvf_19998_199998 = require( './fixtures/julia/erfcinvf_1.9998_1.9999..8.json' );
var erfcinvf_199998_2 = require( './fixtures/julia/erfcinvf_1.9999..8_2.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof erfcinvf, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the inverse complementary error function for `x` on the interval `[0.0002,0.25]`', function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	x = erfcinvf_0002_025.x;
	expected = erfcinvf_0002_025.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		t.strictEqual( isAlmostSameValue( y, e, 5 ), true, 'x: '+x[i]+'. y: '+y+'. E: '+e+'.' );
	}
	t.end();
});

