tape( 'the function computes the inverse complementary error function for `x` on the interval `[1.9999..8,2]`', function test( t ) {
	var expected;
	var x;
	var y;
	var i;
	var e;

	x = erfcinvf_199998_2.x;
	expected = erfcinvf_199998_2.expected;

	for ( i = 0; i < x.length; i++ ) {
		y = erfcinvf( x[ i ] );
		e = f32( expected[ i ] );
		// Handle single-precision vs double-precision differences
		if ( y === -Infinity && ( expected[ i ] === null || ( expected[ i ] < -5.0 ) ) ) {
			t.strictEqual( y, -Infinity, 'x: '+x[i]+'. y: '+y+', expected: -Infinity (single-precision)' );
		} else if ( y === expected[ i ] ) {
			t.strictEqual( y, expected[ i ], 'x: '+x[i]+', y: '+y+', expected: '+expected[i] );
		} else {
			t.strictEqual( isAlmostSameValue( y, e, 5 ), true, 'x: '+x[i]+'. y: '+y+'. E: '+e+'.' );
		}
	}
	t.end();
});

tape( 'the function returns `NaN` if provided `NaN`', function test( t ) {
	var v = erfcinvf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns `NaN` if provided a value outside the domain [0,2]', function test( t ) {
	var v;
	var i;

	for ( i = 0; i < 1e2; i++ ) {
		v = ( randu()*3.0 ) - 1.0; // generates values in [-1, 2]
		if ( v < 0.0 || v > 2.0 ) {
			t.strictEqual( isnanf( erfcinvf( v ) ), true, 'returns expected value when provided '+v );
		}
	}
	t.end();
});
